def isPossible(N: int, P: int, prerequisites: list[set[int]]) -> bool:
    from collections import deque

    # Build adjacency list and in-degree count
    adj = [[] for _ in range(N)]
    in_degree = [0] * N

    for pair in prerequisites:
        u, v = pair
        adj[v].append(u)
        in_degree[u] += 1

    # Initialize queue with tasks having no prerequisites
    queue = deque()
    for task in range(N):
        if in_degree[task] == 0:
            queue.append(task)

    count = 0
    while queue:
        task = queue.popleft()
        count += 1
        for neighbor in adj[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return count == N
